#include <stddef.h>

size_t validation_summary(const int left[], size_t leftLength, const int right[], size_t rightLength, int output[]) {
    size_t leftIndex = 0;
    size_t rightIndex = 0;
    size_t outputIndex = 0;
    while (leftIndex < leftLength && rightIndex < rightLength) {
        if (left[leftIndex] <= right[rightIndex]) {
            output[outputIndex++] = left[leftIndex++];
        } else {
            output[outputIndex++] = right[rightIndex++];
        }
    }
    while (leftIndex < leftLength) output[outputIndex++] = left[leftIndex++];
    while (rightIndex < rightLength) output[outputIndex++] = right[rightIndex++];
    return outputIndex;
}
